const text = input.response || input.text || '';
const risks = text.split('\n').map(l => l.trim()).filter(l => l.toUpperCase().startsWith('RISK:'));
const percentage = Math.max(5, 95 - risks.length * 12);
return { ...input, approvalPercentage: percentage, risks };

const rows = input.records || input.rows || [];
const lastSeenIds = input.lastSeenIds || [];
const readyNow = rows.filter(r => r.fields && r.fields.Status === 'DocsComplete');
const newlyReady = readyNow.filter(r => !lastSeenIds.includes(r.id));
return { ...input, newlyReady, lastSeenIds: readyNow.map(r => r.id) };

const text = input.response || input.text || '';
// Naive flag: any mismatch keyword in AI output
const mismatches = text.split('\n').filter(l => /mismatch|does not match|differ/i.test(l));
return { ...input, mismatches, isMatch: mismatches.length === 0 };

const text = input.response || input.text || '';
const lines = text.split('\n').filter(l => l.includes('|'));
const ranked = lines.map(l => {
  const parts = l.split('|').map(p => p.trim());
  const priorityPart = parts.find(p => p.toLowerCase().startsWith('priority'));
  const priority = priorityPart ? parseInt(priorityPart.split(':')[1]) : 5;
  return { client: parts[0], line: l, priority };
}).sort((a, b) => b.priority - a.priority);
return { ...input, ranked };

const rows = input.records || input.rows || [];
const lastSnapshot = input.lastSnapshot || {};
const changed = [];
for (const r of rows) {
  const prev = lastSnapshot[r.id] || {};
  const diffFields = {};
  for (const key of Object.keys(r.fields)) {
    if (JSON.stringify(prev[key]) !== JSON.stringify(r.fields[key])) diffFields[key] = r.fields[key];
  }
  if (Object.keys(diffFields).length > 0) changed.push({ id: r.id, diffFields, fields: r.fields });
}
const newSnapshot = {}; rows.forEach(r => newSnapshot[r.id] = r.fields);
return { ...input, changed, lastSnapshot: newSnapshot };

