config.code:
const rows = input.records || input.rows || [];
const now = Date.now();
const DAY = 86400000;
const flagged = rows.map(r => {
  const expiry = new Date(r.fields.ExpiryDate).getTime();
  const daysLeft = Math.round((expiry - now) / DAY);
  let urgency = null;
  if (daysLeft <= 7) urgency = 'urgent';
  else if (daysLeft <= 30) urgency = 'soon';
  else if (daysLeft <= 90) urgency = 'upcoming';
  return { ...r.fields, id: r.id, daysLeft, urgency };
}).filter(r => r.urgency);
return { ...input, flagged };

const record = (input.records && input.records[0] && input.records[0].fields) || {};
const reply = `Status for ${record.Name || input.lookupValue}: ${record.Status || 'not found'}. Score: ${record.Score || 'n/a'}. Missing docs: ${record.Missing || 'none on file'}.`;
return { ...input, reply };

const required = { 'Individual': ['PAN Card','Address Proof','Photo ID'], 'Business': ['GST Certificate','PAN Card','Bank Statement','Business Registration'] };
const checklist = required[input.clientType] || required['Business'];
const received = input.receivedTypes || [input.response];
const missing = checklist.filter(doc => !received.includes(doc));
return { ...input, missing, isComplete: missing.length === 0 };

const text = input.response || input.text || '';
const match = text.match(/RISK_LEVEL:\s*(low|medium|high)/i);
const level = match ? match[1].toLowerCase() : 'medium';
const scoreMap = { low: 20, medium: 55, high: 85 };
const riskScore = scoreMap[level];
return { ...input, riskLevel: level, riskScore, isHighRisk: riskScore >= 80 };

const rows = input.records || input.rows || [];
const now = Date.now();
const HOUR = 3600000;
const flagged = rows.map(r => {
  const opened = new Date(r.fields.OpenedAt).getTime();
  const hoursOpen = (now - opened) / HOUR;
  const slaHours = r.fields.SlaHours || 24;
  return { ...r.fields, id: r.id, hoursOpen, isOverdue: hoursOpen > slaHours, isVeryOverdue: hoursOpen > slaHours * 2 };
}).filter(r => r.isOverdue);
return { ...input, flagged };

const rows = input.records || input.rows || [];
const lastSnapshot = input.lastSnapshot || {};
const changed = [];
for (const r of rows) {
  const prev = lastSnapshot[r.id] || {};
  if (JSON.stringify(prev) !== JSON.stringify(r.fields)) changed.push({ id: r.id, previous: prev, current: r.fields });
}
const newSnapshot = {}; rows.forEach(r => newSnapshot[r.id] = r.fields);
return { ...input, changed, lastSnapshot: newSnapshot };

const decision = input.response || {};
const severity = decision.severity || 'low';
const recipient = severity === 'high' ? input.complianceLeadPhone : input.accountManagerPhone;
return { ...input, alertWorthy: decision.alertWorthy, reason: decision.reason, severity, recipient };

const rows = input.records || input.rows || [];
const lastSeenIds = input.lastSeenIds || [];
const readyNow = rows.filter(r => r.fields && r.fields.Status === 'Ready');
const newlyReady = readyNow.filter(r => !lastSeenIds.includes(r.id));
return { ...input, newlyReady, lastSeenIds: readyNow.map(r => r.id) };

